{
System.Windows.Forms.MessageBox.Show("This add-in is
connected.");
}
else
{
System.Windows.Forms.MessageBox.Show("This add-in is not
connected.");
}
}
catch (COMException)
{
System.Windows.Forms.MessageBox.Show("Not a registered add-
in.");
}
}
